        'canvas_intro' => 'எடிட்டர் என்பது மூன்று வடிவ கணுக்களைக் கொண்ட புள்ளி-கட்ட கேன்வாஸ் ஆகும்:',
        'canvas_trigger' => '<strong>தூண்டுதல் கணு</strong> &mdash; அம்பர் நிற மாத்திரை வடிவம், மேல் மையத்தில் பொருத்தப்பட்டிருக்கும். ஒரு பணிப்பாய்விற்கு ஒன்று; நீக்க முடியாது.',
        'canvas_condition' => '<strong>நிபந்தனை கணுக்கள்</strong> &mdash; ஆரஞ்சு நிற வைரங்கள். <em>நிபந்தனை சேர்</em> மூலம் ஒன்றைச் சேர்க்கலாம். மறுவரிசைப்படுத்த இழுக்கவும்.',
        'canvas_action' => '<strong>செயல் கணுக்கள்</strong> &mdash; நீல நிற வட்டமான செவ்வகங்கள். <em>செயல் சேர்</em> மூலம் ஒன்றைச் சேர்க்கலாம். மறுவரிசைப்படுத்த இழுக்கவும்.',
        'canvas_order' => 'இணைப்பிகள் செயலாக்க வரிசையில் தானாக வரையப்படுகின்றன: தூண்டுதல் &rarr; நிபந்தனைகள் (y நிலைப்படி மேலிருந்து கீழ்) &rarr; செயல்கள் (மேலிருந்து கீழ்). <strong>நிலையே வரிசை</strong> &mdash; இரண்டை மாற்ற, ஒரு நிபந்தனையை மற்றொன்றுக்கு மேலே இழுக்கவும்.',
        'canvas_panel' => 'வலதுபுறம் விவரப் பலகத்தைத் திறக்க ஏதேனும் ஒரு கணுவைக் கிளிக் செய்யவும். பலகத்தை மீண்டும் பணிப்பாய்வு நிலை புலங்களுக்கு (பெயர் / விளக்கம் / செயலில் கொடி / சமீபத்திய இயக்கங்கள்) மாற்ற, காலியான கேன்வாஸில் கிளிக் செய்யவும். தேர்ந்தெடுத்த கணுவை (தூண்டுதல் தவிர) அகற்ற, வலது-கிளிக் செய்யவும் அல்லது Delete அழுத்தவும்.',
        'conditions_heading' => 'நிபந்தனைகள்',
        'conditions_intro' => 'நிபந்தனைப் பலகத்தில் மூன்று கட்டுப்பாடுகள் உள்ளன: <strong>புலம்</strong>, <strong>செயலி</strong>, <strong>மதிப்பு</strong>. தேர்ந்தெடுத்த புல வகைக்கு ஏற்ப அவற்றின் நடத்தை மாறுகிறது:',
        'conditions_lookup_heading' => 'தேடல் புலங்கள் (முன்னுரிமை, நிலை, துறை, வகை, பகுப்பாய்வாளர்&hellip;)',
        'conditions_lookup_body' => 'மதிப்புக் கட்டுப்பாடு என்பது தேடல் அட்டவணையிலிருந்து எடுக்கப்பட்ட <strong>உண்மையான மதிப்புகளின் தேர்வுப்பெட்டிப் பட்டியல்</strong> &mdash; புரியாத ஐடிகள் அல்ல. துல்லியமான பொருத்தத்திற்கு ஒன்றைத் தேர்வு செய்யுங்கள், OR முறைக்கு பலவற்றைத் தேர்வு செய்யுங்கள் (எ.கா. <em>"முன்னுரிமை Critical அல்லது High"</em>). செயலி கீழ்விரி <strong>ஆகும் / ஆகாது / காலியாக உள்ளது / காலியாக இல்லை</strong> என சுருங்குகிறது &mdash; மீதியை பல-தேர்வு கையாளுகிறது.',
        'conditions_text_heading' => 'உரை புலங்கள் (பொருள், கோரிக்கையாளர் மின்னஞ்சல், தலைப்பு&hellip;)',
        'conditions_text_body' => 'முழுமையான உரைச் செயலி பட்டியலுடன் எளிய உரை உள்ளீடு: <strong>சமம் / சமமல்ல / இவற்றில் ஒன்று / இவற்றில் ஒன்றல்ல / கொண்டுள்ளது / கொண்டிருக்கவில்லை / காலியாக உள்ளது / காலியாக இல்லை</strong>. <code>gt</code> / <code>lt</code> <em>வழங்கப்படுவதில்லை</em> &mdash; எழுத்துக்கோவை அடிப்படையிலான சரம் ஒப்பீடு ஆபத்தானது.',
        'conditions_num_heading' => 'எண் புலங்கள் (ஐடிகள், கால அளவுகள்&hellip;)',
        'conditions_num_body' => 'எண் செயலிகள்: <strong>சமம் / சமமல்ல / இவற்றில் ஒன்று / இவற்றில் ஒன்றல்ல / விட அதிகம் / விட குறைவு / காலியாக உள்ளது / காலியாக இல்லை</strong>. <em>கொண்டுள்ளது</em> இல்லை &mdash; எண்ணில் துணைச்சரம் தேடுவது பொருளற்றது.',
        'actions_heading' => 'செயல்கள்',
        'actions_th_type' => 'வகை',
        'actions_th_does' => 'இது என்ன செய்கிறது',
        'actions_th_args' => 'முக்கிய ஆர்குமெண்ட்கள்',
        'actions_row1_does' => 'இந்தப் பணிப்பாய்வின் செயலாக்கப் பதிவில் ஒரு செய்தியை எழுதுகிறது. ஒரு விதியை உருவாக்கும்போது இடப்பிடிப்பாகவும், எஞ்சினை முதல் முதல் இறுதி வரை சரிபார்க்கவும் பயனுள்ளது.',
        'actions_row1_args' => 'message',
        'actions_row2_does' => 'ஒரு டிக்கெட்டின் நிலையை மாற்றுகிறது. புதிய நிலையின் <em>is_closed</em> கொடி மாறும்போது <code>closed_datetime</code> ஐ தானாகப் பதிக்கிறது / அழிக்கிறது.',
        'actions_row2_args' => 'ticket_id, status_id',
        'actions_row3_does' => 'ஒரு டிக்கெட்டின் முன்னுரிமையை அமைக்கிறது.',
        'actions_row3_args' => 'ticket_id, priority_id',
        'actions_row4_does' => 'ஒரு டிக்கெட்டின் உரிமையாளர் / ஒதுக்கப்பட்டவரை அமைக்கிறது. வலது பலகத்தின் உரிமையாளர் புலம் ஒத்திசைவில் இருக்க <code>assigned_analyst_id</code> மற்றும் <code>owner_id</code> இரண்டையும் புதுப்பிக்கிறது.',
        'actions_row4_args' => 'ticket_id, analyst_id',
        'actions_row5_does' => 'டிக்கெட்டின் தணிக்கைத் தடத்தில் ஒரு சுதந்திர-உரைக் குறிப்பைச் சேர்க்கிறது. உள்ளகமானது &mdash; கோரிக்கையாளருக்கு ஒருபோதும் அனுப்பப்படாது.',
        'actions_row5_args' => 'ticket_id, note',
        'actions_row6_does' => 'டிக்கெட்டின் அஞ்சல் பெட்டியைப் பயன்படுத்தி டிக்கெட்டின் கோரிக்கையாளருக்கு (அல்லது ஏதேனும் முகவரிக்கு) மின்னஞ்சல் அனுப்புகிறது. பதில்கள் தானாக அதே டிக்கெட்டில் இணைய, பொருளின் தொடக்கத்தில் <code>[SDREF:&hellip;]</code> சேர்க்கப்படும். <strong>டிக்கெட் இப்போது விருப்பத்தேர்வு</strong> &mdash; அதற்குப் பதிலாக அனுப்ப ஒரு அஞ்சல் பெட்டியைத் தேர்ந்தெடுக்கலாம்; டிக்கெட் உருவாகும் முன்பே படிவம் சமர்ப்பிப்பை ஏற்றுக்கொண்டதாகத் தெரிவிப்பது இப்படித்தான். டிக்கெட் இல்லாதபோது பதில் இணைவதற்கு எதுவும் இல்லை, எனவே எங்கும் செல்லாத பதிலுக்கு அழைப்பு விடுப்பதற்குப் பதிலாக &ldquo;இந்த வரிக்கு மேலே பதிலளிக்கவும்&rdquo; குறி சேர்க்கப்படுவதில்லை.',
        'actions_row6_args' => 'ticket_id, to, subject, body',
        'actions_row7_does' => 'ஒரு பணியை உருவாக்குகிறது. <code>ticket_id</code> வழங்கப்பட்டால் மூல டிக்கெட்டுடன் தானாக இணைக்கிறது. நிலை / முன்னுரிமை காலியாக இருந்தால் பணியிடத்தின் இயல்புநிலைகளைப் பயன்படுத்தும்.',
        'actions_row7_args' => 'title, description, status_id, priority_id, assignee_id, ticket_id',
        'actions_row8_does' => 'ஒரு புதிய டிக்கெட்டை உருவாக்குகிறது. <em>"புதிய-பணியாளர் படிவம் &rarr; IT + HR + Facilities டிக்கெட்டுகள்"</em> போன்ற பரவல் பணிப்பாய்வுகளுக்குப் பயனுள்ளது. நிகழ்வு <strong>படிவ சமர்ப்பிப்பைக்</strong> கொண்டிருக்கும்போது, டிக்கெட் சரியான முறையில் தானாக உருவாக்கப்படும் &mdash; கோரிக்கையாளர் அவரது உண்மையான கணக்குடன் பொருத்தப்படுவார், நிறுவனம் அதிலிருந்து எடுக்கப்படும், உடல் காலியாக இருந்தால் சமர்ப்பித்த பதில்கள் அட்டவணையாக அமைக்கப்படும். இங்கே நீங்கள் அமைப்பது எப்போதும் முன்னுரிமை பெறும்; நீங்கள் காலியாக விட்டதை மட்டுமே படிவம் நிரப்பும்.',
        'actions_row8_args' => 'subject, body, priority_id, department_id, type_id, assigned_analyst_id, from_email, from_name',
        'actions_row9_does' => 'வெளிப்புற URL க்கு ஒரு செய்தியை POST செய்கிறது &mdash; Slack, Teams, Discord, PagerDuty, Zapier/Make அல்லது உள்வரும் webhook ஏற்கும் எந்த அமைப்புக்கும் நிகழ்வுகளை அனுப்பலாம். ஒரு அரட்டை முன்னமைவைத் தேர்ந்தெடுங்கள், முழுப் பதிவை (REST API போலவே முழுப் பொருளும் JSON ஆக) அனுப்புங்கள், அல்லது உங்கள் சொந்த JSON உடலை வார்ப்புருவாக்குங்கள். விருப்பமான HMAC கையொப்ப ரகசியத்தை ஆதரிக்கிறது, மேலும் சேமிக்கும் முன் இறுதிப்புள்ளியின் உண்மையான பதிலைக் காட்டும் சோதனை அனுப்பு பொத்தானும் உள்ளது.',
        'actions_row9_args' => 'preset, url, message (presets), body (custom JSON), secret (optional)',
        'actions_note' => 'ஒவ்வொரு செயலிலும் தேவையான ஆர்குமெண்ட்கள் படிவத்தில் <code>*</code> குறியால் குறிக்கப்பட்டிருக்கும். தேவையான ஆர்குமெண்ட்கள் இல்லாவிட்டால் செயல் இயக்க நேரத்தில் தோல்வியடையும் &mdash; எஞ்சின் தோல்வியை செயலாக்க வரிசையில் பதிவு செய்து, சங்கிலியின் மீதியை நிறுத்தும்.',
        'actions_webhook_callout' => '<strong><code>send_webhook</code> செயல் தனக்கென ஒரு பெரிய தலைப்பு</strong> &mdash; அரட்டை முன்னமைவுகள், முழுப் பதிவு பேலோடுகள், HMAC கையொப்பமிடல், சோதனை-அனுப்பு பொத்தான், மறுமுயற்சிகளுடன் பின்னணி விநியோகம், மற்றும் நிலை டாஷ்போர்டு. இதற்கென தனி வழிகாட்டி உள்ளது: <a href="help-webhooks.php"><strong>Webhooks வழிகாட்டி &rarr;</strong></a>',
        'variables_heading' => 'மாறிகள் &mdash; <code>{{path.to.field}}</code>',
        'variables_intro' => 'எந்தவொரு சுதந்திர-உரை செயல் ஆர்குமெண்டும் அதைத் தூண்டிய நிகழ்விலிருந்து மதிப்புகளை எடுக்கலாம். குறியீடுகளை நீங்களே தட்டச்சு செய்ய வேண்டியதில்லை: மாறிகளை ஏற்கும் ஒவ்வொரு புலத்திலும் <strong>மாறிகளுடன் திருத்து</strong> பொத்தான் உள்ளது; அது <strong>பக்கவாட்டில் தேடக்கூடிய மாறிப் பட்டியலுடன்</strong> விசாலமான எடிட்டரைத் திறக்கும் — ஒன்றைக் கிளிக் செய்தால் உங்கள் கர்சர் இருக்கும் இடத்தில் சேரும். ஒவ்வொரு குறியீடும் அது குறிப்பதாக மாற்றப்பட்ட முடிவான உரையை நேரடி முன்னோட்டம் காட்டும்.',
        'variables_scoped' => '<strong>தூண்டுதலால் உண்மையில் நிரப்ப முடிந்த மாறிகள் மட்டுமே உங்களுக்கு வழங்கப்படும்.</strong> இது தோன்றுவதை விட முக்கியமானது: காணாத மாறி பிழையை எழுப்பாது, அது அமைதியாக <em>வெற்று சரமாக</em> மாறும். எனவே <code>knowledge.published</code> மீதான பணிப்பாய்வின் செய்தி <code>{{ticket.subject}}</code> என்று இருந்தால் அது தோல்வியடையாது — பொருள் இருக்க வேண்டிய இடத்தில் வெறுமையை இடும், அது உங்களுக்குத் தெரியவே தெரியாது. அறிவு நிகழ்வில் டிக்கெட் இல்லை, எனவே தேர்வி டிக்கெட் மாறிகளை வழங்கவே வழங்காது, அப்படியும் ஒன்றைத் தட்டச்சு செய்தால் அது வெற்றாக வரும் என்று புலம் எச்சரிக்கும்.',
        'variables_names' => '<strong>ஐடி அல்ல, பெயரைப் பயன்படுத்துங்கள்.</strong> <code>{{ticket.priority_id}}</code> என்பது <code>4</code> ஆக வரும் &mdash; உங்கள் Slack சேனலைப் படிக்கும் யாரும் விளக்க முடியாத எண். எனவே ஒவ்வொரு தேடல் புலத்திற்கும் படிக்கத்தக்க இரட்டை உள்ளது: <code>{{ticket.priority_name}}</code> என்பது <strong>Critical</strong> என வரும். தேர்வி பெயரை சாதாரணத் தேர்வாகப் பட்டியலிடுகிறது (<em>டிக்கெட் &middot; முன்னுரிமை</em>), எண் வடிவத்தை <em>(ஐடி)</em> எனக் குறிக்கிறது, ஏனெனில் ஒருவர் படிக்கும் செய்தியில் பெரும்பாலும் தேவைப்படுவது பெயரே. ஐடிகள் தேவைப்படும்போது &mdash; நிபந்தனைக்கு, அல்லது அவற்றை எதிர்பார்க்கும் பெறும் அமைப்புக்கு &mdash; இன்னும் உள்ளன. மாற்ற தூண்டுதல்களில் <code>{{old_priority_name}}</code> / <code>{{new_priority_name}}</code> உம் கிடைக்கும், எனவே "High இலிருந்து Critical க்கு உயர்த்தப்பட்டது" தானே எழுதிக்கொள்ளும்.',
        'variables_number' => '<strong>வரிசை ஐடி அல்ல, குறிப்பு எண்ணை மேற்கோள் காட்டுங்கள்.</strong> <code>{{ticket.id}}</code> என்பது உள்ளகத் தரவுத்தள ஐடி (<code>83</code>) &mdash; கோரிக்கையாளருக்கு எந்தப் பொருளுமில்லை. <code>{{ticket.number}}</code> என்பது அவர்கள் உங்களிடம் திரும்பக் குறிப்பிடும் குறிப்பு எண் (<code>ETC-623-64409</code>), மின்னஞ்சல் பொருளிலும் அரட்டை எச்சரிக்கையிலும் இருக்க வேண்டியது அதுவே. <code>{{problem.number}}</code> க்கும் அதேபோல். <strong>ஒரு விதிவிலக்கு:</strong> <em>டிக்கெட் ஐடி</em> செயல் ஆர்குமெண்ட் <code>{{ticket.id}}</code> ஆகவே இருக்க வேண்டும் &mdash; அந்தப் புலம் எஞ்சினுக்கு <em>எந்தப் பதிவில் செயல்பட வேண்டும்</em> என்று சொல்கிறது, அது வரிசை ஐடியால் தேடுகிறது. ஒருவர் படிக்கும் சொற்களில் எண்ணைப் பயன்படுத்துங்கள்; குழாய்வேலையில் ஐடியை விடுங்கள்.',
        'variables_full' => 'ஒரு தூண்டுதல் முழுப் பதிவையும் கொண்டிருக்கும்போது, உங்களுக்கு <code>{{&lt;object&gt;.full}}</code> உம் கிடைக்கும் &mdash; எ.கா. <code>{{ticket.full}}</code> &mdash; இது REST API திருப்பும் அதே வடிவத்தில் முழுப் பதிவையும் JSON ஆக உட்பொதிக்கிறது. மேலும் <code>{{event}}</code> எப்போதும் தூண்டிய தூண்டுதலின் பெயராக மாறும்.',
        'variables_common' => 'டிக்கெட் தூண்டுதல்களுக்கான பொதுவான மாறிகள்:',
        'variables_li1' => '<code>{{ticket.id}}</code>, <code>{{ticket.subject}}</code>, <code>{{ticket.priority_id}}</code>, <code>{{ticket.status_id}}</code>',
        'variables_li2' => '<code>{{ticket.department_id}}</code>, <code>{{ticket.type_id}}</code>, <code>{{ticket.assigned_analyst_id}}</code>',
        'variables_li3' => '<code>{{ticket.owner_id}}</code>, <code>{{ticket.created_by}}</code>, <code>{{ticket.requester_email}}</code>',
        'variables_li4' => '<code>ticket.status_changed</code> / <code>ticket.priority_changed</code> க்கு: மேலும் <code>{{old_status_id}}</code>, <code>{{new_status_id}}</code>, <code>{{old_priority_id}}</code>, <code>{{new_priority_id}}</code>',
        'variables_li5' => '<code>ticket.assigned</code> க்கு: மேலும் <code>{{analyst_id}}</code>, <code>{{team_id}}</code>',
        'variables_tip' => '<strong>சிறந்த நடைமுறை:</strong> செயல் <code>ticket_id</code> புலங்களில், குறிப்பிட்ட ஐடியைத் தட்டச்சு செய்வதற்குப் பதிலாக இயல்புநிலை <code>{{ticket.id}}</code> ஐ விடுங்கள் &mdash; அப்போது பணிப்பாய்வு நிலையான டிக்கெட்டில் அல்லாமல், அதைத் தூண்டிய டிக்கெட்டில் செயல்படும்.',
        'variables_chain_heading' => 'முந்தைய செயல் உருவாக்கியதைப் பயன்படுத்துதல்',
        'variables_chain_intro' => 'செயல்கள் வரிசையாக இயங்கும், பிந்தைய செயல் முந்தையது செய்ததைக் குறிப்பிடலாம். இதனால்தான் <em>&ldquo;ஒரு டிக்கெட்டை உருவாக்கி, பின்னர் அவர்களுக்கு டிக்கெட் எண்ணை மின்னஞ்சல் செய்யுங்கள்&rdquo;</em> என்பது சாத்தியமற்றதாக இல்லாமல் ஒரே பணிப்பாய்வாக ஆகிறது.',
        'variables_chain_last' => '<code>{{last.ticket_id}}</code> &mdash; இதற்கு உடனடியாக முன்பிருந்த செயல் உருவாக்கியது.',
        'variables_chain_steps' => '<code>{{steps.1.ticket_number}}</code> &mdash; கேன்வாஸில் அதன் அருகே காட்டப்படும் எண்ணால் குறிப்பிடப்படும் ஒரு குறிப்பிட்ட செயல். உங்களுக்கு வேண்டிய செயல் நேரடியாக முந்தையதாக இல்லாதபோது இதைப் பயன்படுத்துங்கள்.',
        'variables_chain_note' => 'இவை பணிப்பாய்வின் சொந்தத் தரவை மேலெழுதாமல் வேண்டுமென்றே தங்களுக்கென தனிப் பெயர்களில் உள்ளன. டிக்கெட்டை உருவாக்குவது <code>{{ticket.id}}</code> ஐ மாற்றினால், டிக்கெட் பணிப்பாய்வின் ஒவ்வொரு பிந்தைய படியும் பணிப்பாய்வைத் தொடங்கிய டிக்கெட்டுக்குப் பதிலாக புதிய டிக்கெட்டை அமைதியாகச் சுட்டத் தொடங்கும்.',
        'actions_forms_callout' => '<strong>படிவங்களும் இந்தச் செயல்களை இயக்கலாம்.</strong> பணிப்பாய்வை உருவாக்குவதற்குப் பதிலாக, ஒரு படிவத்தைத் திறந்து அதன் <strong>அடுத்து என்ன நடக்கும்</strong> தாவலில் அது சமர்ப்பிக்கப்படும்போது, அங்கீகரிக்கப்படும்போது அல்லது நிராகரிக்கப்படும்போது என்ன நடக்க வேண்டும் என்று சொல்லலாம். இது அதே எஞ்சின், அதே செயல்கள், இயக்கங்களும் அதே செயலாக்கப் பதிவில் தோன்றும் &mdash; படிவ எடிட்டர் என்பது அந்த ஒரு படிவத்துக்கு மட்டுமான இரண்டாவது நுழைவாயில். ஒரு விதி பல படிவங்களை உள்ளடக்க வேண்டியிருக்கும்போது இங்கே பணிப்பாய்வை உருவாக்குங்கள்.',
        'ai_heading' => 'AI இணை-ஆசிரியர்',
        'ai_intro' => 'கருவிப்பட்டியில் <strong>AI இணை-ஆசிரியர்</strong> ஐக் கிளிக் செய்து, பணிப்பாய்வை எளிய ஆங்கிலத்தில் விவரியுங்கள். AI ஒரு கட்டமைக்கப்பட்ட முன்மொழிவைத் தரும் &mdash; தூண்டுதல், நிபந்தனைகள், செயல்கள் &mdash; அதை கேன்வாஸில் <em>பயன்படுத்து</em> அல்லது <em>நிராகரி</em> செய்யலாம்.',
        'ai_examples' => 'நன்றாக வேலை செய்யும் எடுத்துக்காட்டுகள்:',
        'ai_ex1' => '<em>"Critical-முன்னுரிமை டிக்கெட் உருவாக்கப்படும்போது, \'P1 &mdash; please respond within 15 minutes\' என்று ஒரு குறிப்பைச் சேர்."</em>',
        'ai_ex2' => '<em>"<code>finance@acme.com</code> இலிருந்து டிக்கெட் உருவாக்கப்படும்போது, அதை எனக்கு ஒதுக்கி முன்னுரிமையை High ஆக அமை."</em>',
        'ai_ex3' => '<em>"ஒரு டிக்கெட் மூடப்படும்போது, கோரிக்கையாளருக்கு நன்றி தெரிவித்து கருத்து கேட்டு மின்னஞ்சல் அனுப்பு."</em>',
        'ai_catalogue' => 'AI எஞ்சினின் முழுப் பட்டியலையும் அறியும் &mdash; ஒவ்வொரு தூண்டுதல், நிபந்தனைச் செயலி, செயல், மற்றும் கிடைக்கும் தேடல் அட்டவணை மதிப்புகள் &mdash; எனவே உண்மையில் வேலை செய்யக்கூடியவற்றை மட்டுமே முன்மொழியும். ஏற்கனவே உள்ள பணிப்பாய்வை மேம்படுத்தினால் (<em>"இப்போது Finance க்கு மட்டும் பொருத்து"</em> / <em>"டிக்கெட் ஐடியைப் பதிவு செய்ய ஒரு செயலைச் சேர்"</em>) முதலில் இருந்து தொடங்காமல் கேன்வாஸில் உள்ளதையே திருத்தும்.',
        'ai_config' => 'வழங்குநர் (Anthropic / OpenAI), மாதிரி மற்றும் API key ஐ <strong>பணிப்பாய்வு &rarr; அமைப்புகள் &rarr; AI</strong> இல் அமைக்கவும். கட்டணமும் அணுகலும் நுணுக்கமாக இருக்க விசைகள் ஒவ்வொரு தொகுதிக்கும் தனியாகச் சேமிக்கப்படுகின்றன.',
        'templates_heading' => 'டெம்ப்ளேட்டிலிருந்து தொடங்குங்கள்',
        'templates_intro' => 'பணிப்பாய்வுகள் பட்டியலில் உள்ள <strong>டெம்ப்ளேட்டிலிருந்து புதியது</strong> பொத்தான், பெரும்பாலான சேவை மையங்கள் முதலில் தானியக்கமாக்கும் வேலைகளுக்கான தயார் செய்முறைகளின் தொகுப்பைத் திறக்கும் &mdash; புதிய டிக்கெட்டை தானாக ஏற்றுக்கொள்ளுதல், P1 இல் குழுவுக்கு எச்சரிக்கை, புதிய-பணியாளர் படிவத்தை IT, HR மற்றும் Facilities டிக்கெட்டுகளாகப் பரப்புதல், மாற்றம் அங்கீகரிக்கப்படும்போது செயல்படுத்தல் பணியை உருவாக்குதல். அவற்றில் நான்கு <strong>நேர அடிப்படையிலானவை</strong>: SLA மீறப்படுவதற்கு <em>முன்பே</em> டிக்கெட்டை உயர்த்துதல், மீறப்பட்டதும் எச்சரித்தல், ஒப்பந்தம் அல்லது சொத்து உத்தரவாதம் காலாவதியாகப் போகிறது என்று நினைவூட்டுதல். ஒன்றைத் தேர்ந்தெடுத்தால் அது சாதாரணமான, முழுமையாகத் திருத்தக்கூடிய பணிப்பாய்வாக உங்கள் பணிப்பாய்வுகளில் நகலெடுக்கப்படும். அதன் பிறகு அதில் சிறப்பு எதுவுமில்லை: பெயர் மாற்றவும், மறுஇணைக்கவும் அல்லது நீக்கவும் உங்கள் விருப்பம். தொகுப்பு <strong>வகை</strong> மற்றும் <strong>தேடல்</strong> மூலம் வடிகட்டுகிறது &mdash; தேடல் விளக்கம், தூண்டுதல் மற்றும் செயல்களையும் அடையும், எனவே <em>expiry</em>, <em>slack</em> அல்லது <em>wipe</em> என்று தட்டச்சு செய்தால் பெயரில் அந்தச் சொல் இல்லாவிட்டாலும் செய்முறை கிடைக்கும்.',
        'templates_lookups' => 'ஒவ்வொரு நிறுவலும் தனது சொந்த நிலைகளையும் முன்னுரிமைகளையும் பெயரிடுகிறது, எனவே டெம்ப்ளேட் அவற்றை நேரடியாக எழுத முடியாது. அதற்குப் பதிலாக அது <em>"இந்த நிறுவல் Closed என்று அழைப்பது எதுவோ அது"</em> என்று சொல்கிறது, நகலெடுக்கும்போது உண்மையான மதிப்பைத் தேடிக்கொள்கிறோம். எங்களால் பொருத்த முடியாதவை &mdash; உங்களிடம் இல்லாத முன்னுரிமை, அல்லது Slack webhook URL போன்ற உங்களுக்கு மட்டுமே தெரிந்த மதிப்பு &mdash; காலியாக விடப்பட்டு எடிட்டரின் மேலே உள்ள பதாகையில் பட்டியலிடப்படும், எனவே இன்னும் உங்கள் கவனம் தேவைப்படுவது என்ன என்பதைத் தெளிவாகக் காணலாம்.',
        'templates_scheduled' => 'நான்கு நேர அடிப்படை செய்முறைகள் இயங்க ஒரு <strong>திட்டமிடப்பட்ட பணி</strong> தேவை, ஏனெனில் அவை கண்காணிப்பவற்றில் எதுவும் நிகழ்வு அல்ல &mdash; SLA அமைதியாக நேரம் முடியும்போது யாரும் எதையும் சேமிப்பதில்லை, எனவே ஒரு பணி தேடிச் செல்ல வேண்டும். crons திட்டமிடப்படாவிட்டால் இந்தப் பணிப்பாய்வுகள் செயலில் இருந்தும் ஒருபோதும் தூண்டப்படாது. இரண்டு காலாவதி நினைவூட்டல்களும் <strong>90, 30, 7 மற்றும் 1 நாட்கள்</strong> முன்னதாக தூண்டப்படும், ஒவ்வொரு செய்முறையும் 30-நாள் ஒன்றுக்கு வடிகட்டுகிறது &mdash; ஒவ்வொரு இடைவெளியிலும் தெரிவிக்கப்பட அந்த நிபந்தனையை மாற்றுங்கள் அல்லது நீக்குங்கள். <a href="#triggers">தூண்டுதல்கள்</a> ஐப் பார்க்கவும்.',
        'templates_callout' => 'நகலெடுத்த டெம்ப்ளேட் எப்போதும் <strong>அணைக்கப்பட்ட</strong> நிலையில் வரும். நீங்கள் அதைப் படித்து, இடைவெளிகளை நிரப்பி, <em>செயலில்</em> ஐத் தேர்வு செய்யும் வரை அதில் உள்ள எதுவும் தூண்டப்படாது &mdash; முதலில் <strong>உலர் ஓட்டம்</strong> செய்து அது சரியாக என்ன செய்யும் என்பதையும் பார்க்கலாம்.',
        'testing_heading' => 'சேமித்தலும் சோதித்தலும்',
        'testing_save' => 'கருவிப்பட்டியில் உள்ள நிலைச் சுட்டி <em>சேமிக்கப்படவில்லை</em> / <em>சேமிக்கிறது&hellip;</em> / <em>சேமிக்கப்பட்டது</em> எனக் காட்டும். நிலைநிறுத்த <strong>சேமி</strong> ஐக் கிளிக் செய்யுங்கள். பூஜ்ஜிய செயல்களுடன் நடப்பு வரைவுகளைச் சேமிக்கலாம் &mdash; தடுக்கப்படுவதற்குப் பதிலாக "இந்தப் பணிப்பாய்வில் இன்னும் செயல்கள் இல்லை" என்ற மென்மையான எச்சரிக்கை மட்டும் கிடைக்கும்.',
        'testing_dry_heading' => 'உலர் ஓட்டம் &mdash; செய்யாமலே அது என்ன செய்யும் என்று பாருங்கள்',
        'testing_dry_body' => '<strong>உலர் ஓட்டம்</strong> நிபந்தனைகளை உண்மையாக மதிப்பிடுகிறது, பின்னர் ஒவ்வொரு செயலையும் நிறைவேற்றாமல் <em>விவரிக்கிறது</em>. இயக்கம் <em>உலர் ஓட்டம்</em> எனக் குறிக்கப்பட்டு <em>சமீபத்திய இயக்கங்களில்</em> தோன்றும்; <code>{{variables}}</code> ஏற்கனவே நிரப்பப்பட்டு, அது எடுத்திருக்கும் ஒவ்வொரு செயலையும் பட்டியலிடும் &mdash; எனவே உண்மையான மின்னஞ்சல் பொருள், உண்மையான அரட்டைச் செய்தி, உண்மையான குறிப்பைப் படிக்கலாம்.',
        'testing_dry_safe' => 'எதுவும் எழுதப்படுவதில்லை, மின்னஞ்சல் செய்யப்படுவதில்லை, வரிசையில் இடப்படுவதில்லை, அனுப்பப்படுவதில்லை: டிக்கெட் மாற்றங்கள் இல்லை, குறிப்புகள் இல்லை, webhook விநியோகங்கள் இல்லை, பணிப்பாய்வின் இயக்க எண்ணிக்கையும் தொடப்படாது. அதனால் நேரடி பணிப்பாய்வில் பாதுகாப்பாகப் பயன்படுத்தலாம் &mdash; புதிதாக நகலெடுத்த டெம்ப்ளேட்டுக்கு செய்ய வேண்டிய முதல் விவேகமான விஷயமும் இதுவே. (எந்த கையொப்ப ரகசியமும் வெளியீட்டில் மீண்டும் காட்டப்படாமல் மறைக்கப்படும்.)',
        'testing_log_heading' => 'செயலாக்கப் பதிவு &mdash; உண்மையில் என்ன நடந்தது',
        'testing_log_why' => 'இது தோன்றுவதை விட முக்கியமானது. எஞ்சின் <strong>வேண்டுமென்றே தன் சொந்தப் பிழைகளை விழுங்குகிறது</strong> &mdash; பழுதான பணிப்பாய்வு அதைத் தூண்டிய டிக்கெட் சேமிப்பை ஒருபோதும் உடைக்கக் கூடாது. அது சரியான முடிவு, ஆனால் தோல்வியடையும் பணிப்பாய்வு வேறுவிதமாக <em>முற்றிலும் அமைதியாக</em> இருக்கும் என்றும் அர்த்தம். எதுவும் உங்களுக்குச் சொல்லாது. அந்த அமைதியை உடைப்பவை செயலாக்கப் பதிவும், (கடந்த 24 மணி நேரத்தில் தோல்விகள், லூப்-பாதுகாப்பு நிறுத்தங்கள் மற்றும் மறுமுயற்சியை விட்ட webhooks ஐ வெளிக்காட்டும்) <strong>Watchtower இல் உள்ள பணிப்பாய்வுகள் அட்டையும்</strong> ஆகும்.',
        'testing_fire_heading' => 'சோதனை இயக்கம் &mdash; உண்மையாகவே இயக்குதல்',
        'testing_fire' => '<strong>சோதனை இயக்கம்</strong> பணிப்பாய்வை அதன் சொந்த நிபந்தனைகளிலிருந்து உருவாக்கிய செயற்கை பேலோடுடன் உண்மையாகவே இயக்குகிறது, எனவே செயல் பாதை உண்மையில் செயல்படுகிறது &mdash; அது உண்மையிலேயே அந்த மின்னஞ்சலை அனுப்பும். முடிவு நிலையுடன் (<em>வெற்றி / தோல்வி / தவிர்க்கப்பட்டது</em>) மற்றும் முழு படிப் பதிவுடன் <em>சமீபத்திய இயக்கங்களில்</em> சேரும்.',
        'testing_real' => 'உண்மையான தரவுடன் சோதிக்க, அதைத் தூண்டும் செயலைச் செய்தாலே போதும் &mdash; ஒரு டிக்கெட்டை ஒதுக்கவும், அதன் முன்னுரிமையை மாற்றவும், இப்படி. ஹோஸ்ட் தொகுதியிலிருந்து (டிக்கெட்டுகள்) அனுப்புதல் நேரலையில் உள்ளது; செயல்படுத்தல் பதிவு ஒவ்வொரு தூண்டுதலையும் காட்டுகிறது.',
        'triggers_heading' => 'தூண்டுதல் பட்டியல்',
        'triggers_intro' => 'இப்போது பட்டியல் <strong>ஒவ்வொரு தொகுதியையும் உள்ளடக்கியது &mdash; 138 தூண்டுதல்கள், இன்னும் வளர்கிறது</strong>; அனைத்தும் இணைக்கப்பட்டு நேரலையில் உள்ளன. அவை இரண்டு வகைப்படும்:',
        'triggers_time_heading' => 'நேர அடிப்படையிலான தூண்டுதல்கள் &mdash; அவற்றுக்குத் தேவையான cron',
        'triggers_time_body' => 'பெரும்பாலான தூண்டுதல்கள் ஒரு <strong>எழுதும் வழியிலிருந்து</strong> இயங்குகின்றன: யாரோ ஒரு டிக்கெட்டைச் சேமித்தார், எனவே தூண்ட ஒரு தருணம் இருக்கிறது. நான்கு அப்படி இல்லை. <code>sla.warning</code>, <code>sla.breached</code>, <code>contract.expiring</code> மற்றும் <code>asset.warranty_expiring</code> நிகழ்வுகளே அல்ல &mdash; <em>எதுவும் நடக்கவில்லை, நேரம் கடந்தது</em> &mdash; எனவே ஒரு திட்டமிட்ட பணி அவற்றைத் தேடிச் செல்ல வேண்டும்.',
        'triggers_time_cron' => '<strong>அந்த cron-கள் திட்டமிடப்படவில்லை என்றால், இந்தத் தூண்டுதல்கள் ஒருபோதும் இயங்காது.</strong> பணிப்பாய்வு செயலில் இருந்தும் எதுவும் செய்யாமல் இருக்கும். SLA நிகழ்வுகள் SLA மீறல் சரிபார்ப்பு cron-இலிருந்து வருகின்றன (ஒவ்வொரு 5 நிமிடமும்); காலாவதி நிகழ்வுகள் <code>cron/workflow_scheduled.php</code>-இலிருந்து வருகின்றன (மணிக்கு ஒருமுறை போதும்). அமைவு: <code>docs/workflow-scheduled-cron-setup.md</code>, அல்லது <a href="https://github.com/edmozley/freeitsm/wiki/Time-Based-Triggers" target="_blank" rel="noopener noreferrer">விக்கியில் Time-Based Triggers</a>; இன்னும் உண்மையாக இருக்கும் நிலை (மீறப்பட்ட SLA மீறப்பட்டதாகவே இருக்கும்) ஏன் ஒவ்வொரு சில நிமிடங்களுக்கும் மீண்டும் தூண்டப்படுவதில்லை என்பதையும் அது விளக்குகிறது.',
        'triggers_time_once' => 'நேர அடிப்படையிலான நிலை <strong>உண்மையாகவே இருக்கும்</strong> &mdash; மீறப்பட்ட SLA ஐந்து நிமிடங்களுக்குப் பிறகும் மீறப்பட்டதே &mdash; எனவே FreeITSM ஒரு பேரேட்டை வைத்திருக்கிறது; ஒவ்வொரு சூழ்நிலையும் <strong>சரியாக ஒரு முறை</strong> தூண்டப்படும். அதன் அடிப்படையில் உள்ளது மாறும்போது அது மீண்டும் தயாராகிறது: ஒரு டிக்கெட்டின் முன்னுரிமையை உயர்த்தினால் அதன் SLA இலக்கு சுருங்கும், எனவே புதிய, இறுக்கமான காலக்கெடு மீண்டும் உயர்த்தப்பட அனுமதிக்கப்படும். ஒரு ஒப்பந்தத்தைப் புதுப்பித்தால் அடுத்த ஆண்டின் நினைவூட்டல்களும் தூண்டப்படும். காலாவதிகள் <strong>90, 30, 7 மற்றும் 1 நாட்களுக்கு</strong> முன் தூண்டப்படுகின்றன, ஒவ்வொன்றும் <code>window_days</code>-ஐக் கொண்டிருக்கும் &mdash; எனவே "30 நாட்களில் மட்டும் நினைவூட்டு" என்பது ஒரு நிபந்தனை மட்டுமே.',
        'triggers_family_domain' => '<strong>செறிவான டொமைன் நிகழ்வுகள்</strong> &mdash; முழு வகைப்படுத்தப்பட்ட பேலோடுடன் கூடிய அர்த்தமுள்ள வாழ்க்கைச் சுழற்சித் தருணங்கள்: <code>ticket.created</code>, <code>ticket.status_changed</code>, <code>change.approved</code>, <code>problem.status_changed</code>, <code>task.completed</code>, <code>project.health_changed</code>, <code>service_status.incident_resolved</code>, <code>software.application_discovered</code>, மேலும் பல.',
        'triggers_family_forms' => '<strong>படிவங்கள் மற்றும் பட்டியல் கோரிக்கைகள்</strong> &mdash; சாதாரண படிவத்துக்கு <code>form.submitted</code> தூண்டப்படுகிறது. ஒப்புதல் தேவைப்படும் படிவம் அதற்குப் பதிலாக <code>catalogue_request.submitted</code>-ஐத் தூண்டுகிறது; பின்னர் உங்கள் ஒப்புதல் அளிப்பவர் முடிவு செய்ததும் <code>catalogue_request.approved</code> அல்லது <code>catalogue_request.rejected</code>. தனி நிகழ்வு வேண்டுமென்றே வைக்கப்பட்டது: சமர்ப்பிக்கும்போது டிக்கெட் உருவாக்கும் விதி, நீங்கள் கேட்ட ஒப்புதலைத் தாண்டிச் செல்ல முடியாது என்பதே இதன் பொருள். நான்கும் சமர்ப்பிக்கப்பட்ட பதில்களைக் கொண்டுள்ளன, எனவே <code>{{submission.fields.Device type}}</code> ஒவ்வொரு கட்டத்திலும் வேலை செய்யும், மேலும் நான்கையும் ஒரே படிவத்துக்குக் குறுக்கலாம்.',
        'triggers_family_crud' => '<strong>உருவாக்கு / புதுப்பி / நீக்கு நிகழ்வுகள்</strong> &mdash; மீண்டும் பயன்படுத்தக்கூடிய ஒவ்வொரு பதிவும் அமைப்புகள் தேடல் பட்டியலும் <code>&lt;entity&gt;.created</code> / <code>.updated</code> / <code>.deleted</code> என்பதை வெளியிடுகிறது: டிக்கெட்டுகள், சொத்துகள், மாற்றங்கள், சிக்கல்கள், பணிகள், CMDB, ஒப்பந்தங்கள் &amp; வழங்குநர்கள், நாட்காட்டி, மென்பொருள் உரிமங்கள், நெட்வொர்க் வரைபடங்கள், மற்றும் அவற்றின் அனைத்து அமைப்புப் பட்டியல்கள் (நிலைகள், முன்னுரிமைகள், வகைகள், குறிச்சொற்கள்&hellip;).',
        'triggers_picker' => 'பட்டியல் பல டஜன் நீளம் என்பதால், எடிட்டரின் <strong>தூண்டுதல் தேர்வி தேடக்கூடியது</strong> &mdash; வடிகட்ட தட்டச்சு செய்யத் தொடங்குங்கள் (<code>resolved</code>, <code>contract</code>, <code>delete</code>&hellip;). ஒவ்வொரு நிகழ்வும் <strong>ஒரே பகிரப்பட்ட எழுதும் வழியிலிருந்து</strong> தூண்டப்படுகிறது, எனவே மாற்றம் உலாவியிலிருந்து, REST API-யிலிருந்து அல்லது மற்றொரு பணிப்பாய்விலிருந்து வந்தாலும் அது ஒரே மாதிரி நடந்துகொள்ளும் &mdash; மாறுபடாது.',
        'failures_heading' => 'இயந்திரத் தோல்விகள் தனிமைப்படுத்தப்படுகின்றன',
        'failures_callout' => '<strong>பிழையுள்ள பணிப்பாய்வு ஹோஸ்ட் தொகுதியின் கோரிக்கையை உடைக்க முடியாது.</strong> ஒவ்வொரு அனுப்புதலும் try/catch-இல் சுற்றப்பட்டுள்ளது, ஒவ்வொரு செயலின் தோல்வியும் சங்கிலியை நிறுத்தாமல் செயல்படுத்தல் வரிசையில் பதிவு செய்யப்படுகிறது. ஒரு பணிப்பாய்வு நீங்கள் எதிர்பார்த்தபடி செயல்படவில்லை என்றால், பணிப்பாய்வின் <em>சமீபத்திய இயக்கங்கள்</em> பலகத்தைப் பாருங்கள் &mdash; தோல்விகள் அங்கே அடிப்படைப் பிழையுடன் தோன்றும், அவற்றைத் தூண்டிய பக்கத்தில் 500 ஆக அல்ல.',
        'ahead_heading' => 'இன்னும் வரவிருப்பவை',
        'ahead_li1' => '<strong>நிலை 3 செயல்கள்</strong> &mdash; Microsoft Graph: <code>graph_add_to_group</code>, <code>graph_assign_license</code>, <code>graph_disable_user</code>. கட்டண ITSM தொகுப்புகளுடன் ஒப்பிடும்போது இந்தத் தொகுதியின் இருப்பை நியாயப்படுத்தும் புதிய-பணியாளர் / விலகுபவர் தானியக்கங்கள். ஏற்கனவே உள்ள டெனன்ட் OAuth கட்டமைப்பை மீண்டும் பயன்படுத்துகிறது.',
        'ahead_li4' => '<strong>உலர் இயக்கப் பயன்முறை</strong> &mdash; உண்மையான நிகழ்வுக்கு எதிராக ஒரு பணிப்பாய்வை இயக்கி, செயல்களைச் செயல்படுத்தாமல் <em>பதிவு</em> செய்யுங்கள். நேரலையில் மாற்றுவதற்கு முன் என்ன நடந்திருக்கும் என்பதைப் பார்க்கலாம்.',
        'ahead_li5' => '<strong>தொடக்க செய்முறைகள்</strong> &mdash; பொதுவான முறைகளுக்கான நகலெடுக்கக்கூடிய டெம்ப்ளேட்கள்: புதிய-பணியாளர் ஆன்போர்டிங், P1 சம்பவ பதில், SLA-மீறல் உயர்த்துதல், உரிம-புதுப்பித்தல் நினைவூட்டல்.',
        'ahead_li6' => '<strong>Watchtower ஒருங்கிணைப்பு</strong> &mdash; தோல்வியடைந்த இயக்கங்கள் கவன அட்டைகளாகத் தோன்றும்.',
        'ahead_li7' => '<strong>பணிப்பாய்வு பதிப்பாக்கம்</strong> &mdash; வரைவு / வெளியிடு / திரும்பப்பெறு.',
        'ahead_li8' => '<strong>ஸ்ட்ரீமிங் AI இணை-ஆசிரியர்</strong> &mdash; கேன்வாஸ் உருவாகும்போது claude.ai பாணியில் நேரடி வெளியீடு.',
    ],
];
